package com.example.minicommerce.order.domain;import static org.assertj.core.api.Assertions.*;import com.example.minicommerce.order.infrastructure.OrderEntity;import com.example.minicommerce.shared.error.BusinessException;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;import org.junit.jupiter.api.Test;class OrderEntityTest{private OrderEntity order(String n){return new OrderEntity(UUID.randomUUID(),n,1L,new BigDecimal("100"),BigDecimal.ZERO,new BigDecimal("100"),"JPY",null,Instant.parse("2026-01-01T00:00:00Z"));}@Test void cancelledOrder_cannotBePaid(){OrderEntity o=order("MC-X");o.cancel(Instant.parse("2026-01-01T00:00:01Z"));assertThatThrownBy(()->o.markPaid(UUID.randomUUID(),Instant.now())).isInstanceOf(BusinessException.class);}@Test void duplicateCancel_reportsNoSecondSideEffect(){OrderEntity o=order("MC-Y");assertThat(o.cancel(Instant.now())).isTrue();assertThat(o.cancel(Instant.now())).isFalse();assertThat(o.getStatus()).isEqualTo(OrderStatus.CANCELLED);}@Test void refundFailure_returnsPaidForSafeRetry(){OrderEntity o=order("MC-Z");o.markPaid(UUID.randomUUID(),Instant.now());o.requestRefund(Instant.now());o.refundFailed(Instant.now());assertThat(o.getStatus()).isEqualTo(OrderStatus.PAID);}}
